export const HUMAN_PERFORMANCE_QUESTIONS: AirLawQuestion[] = [
  ...HP_SPECIMEN_QUESTIONS,
  ...HP_REVISION_QUESTIONS,
  ...HP_GAP_QUESTIONS,
];

export function getHumanPerformanceQuestionsBySection(sectionId: string): AirLawQuestion[] {
  return HUMAN_PERFORMANCE_QUESTIONS.filter((x) => x.sectionId === sectionId);
}
